// Devuelve los maridajes de un ingrediente (clave en ingles), ya separados
// por intensidad. Si el ingrediente no existe en el libro, devuelve null.
export function getPairings(name) {
  const entry = FLAVOR_PAIRINGS[name?.toLowerCase()?.trim()];
  if (!entry) return null;
  const out = { star: [], strong: [], normal: [] };
  for (const raw of entry.p) {
    if (raw.startsWith('*')) out.star.push(raw.slice(1));
    else if (raw.startsWith('!')) out.strong.push(raw.slice(1));
    else out.normal.push(raw);
  }
  return { ...out, affinities: entry.aff ?? [], season: entry.season ?? null };
}
